code.cpp:
class Solution {
public:
    bool checkStrings(string s1, string s2) {
        int n = s1.size();
        int cnt1[2][26] = {0}, cnt2[2][26] = {0};
        for (int i = 0; i < n; i++) {
            cnt1[i % 2][s1[i] - 'a']++;
            cnt2[i % 2][s2[i] - 'a']++;
        }
        for (int p = 0; p < 2; p++) {
            for (int c = 0; c < 26; c++) {
                if (cnt1[p][c] != cnt2[p][c]) return false;
            }
        }
        return true;
    }
};
